set-variable.value:
@{
        var b = (JObject)context.Variables["body"];
        var m = b["model"];
        return m == null ? "" : ((string)m ?? "");
    }

@{
        var b = (JObject)context.Variables["body"];
        var msgs = b["messages"] as JArray;
        string text = "";
        if (msgs != null) {
            foreach (var m in msgs) {
                var c = m["content"];
                if (c == null) { continue; }
                if (c.Type == JTokenType.String) {
                    text += (string)c + "\n";
                } else if (c.Type == JTokenType.Array) {
                    foreach (var part in (JArray)c) {
                        var t = part["text"];
                        if (t != null) { text += (string)t + "\n"; }
                    }
                }
            }
        }
        return text;
    }

@{
        int tokens = (int)context.Variables["promptTokens"];
        int th = int.Parse("{{length-threshold-tokens}}");
        return tokens < th ? 0 : (tokens < th * 4 ? 1 : 2);
    }

@{
        string text = ((string)context.Variables["promptText"]).ToLowerInvariant();
        var b = (JObject)context.Variables["body"];
        int score = 0;

        // code or query-like content
        if (text.Contains("```") || text.Contains("def ") || text.Contains("class ") || text.Contains("select ") || text.Contains("function ")) { score += 2; }

        // reasoning / analysis verbs (max 3 points)
        string[] kw = new string[] { "step by step", "explain why", "analyze", "analyse", "compare", "trade-off", "tradeoff",
                                     "prove", "derive", "optimize", "architecture", "evaluate", "design a", "strategy", "root cause", "pros and cons" };
        int hits = 0;
        foreach (var k in kw) { if (text.Contains(k)) { hits++; } }
        score += Math.Min(hits, 3);

        // several questions in one prompt
        int q = text.Split(new char[] { '?' }).Length - 1;
        if (q > 3) { score += 2; } else if (q > 1) { score += 1; }

        // math
        if (text.Contains("integral") || text.Contains("theorem") || text.Contains("equation") || text.Contains("probability")) { score += 1; }

        // long conversations
        var msgs = b["messages"] as JArray;
        if (msgs != null && msgs.Count > 6) { score += 1; }

        return score;
    }

@{
        int score = (int)context.Variables["complexityScore"];
        int th = int.Parse("{{complexity-threshold}}");
        return score < th ? 0 : (score < th * 2 ? 1 : 2);
    }

send-request.set-body:
@{
              string text = (string)context.Variables["promptText"];
              if (text.Length > 4000) { text = text.Substring(0, 4000); }
              var req = new JObject(
                  new JProperty("model", "{{model-classifier}}"),
                  new JProperty("max_completion_tokens", 16),
                  new JProperty("messages", new JArray(
                      new JObject(
                          new JProperty("role", "system"),
                          new JProperty("content", "You are a prompt complexity classifier. Reply with exactly one word: simple (chit-chat, lookups, short factual), medium (summaries, rewrites, moderate reasoning) or complex (multi-step reasoning, code design, deep analysis).")),
                      new JObject(
                          new JProperty("role", "user"),
                          new JProperty("content", text)))));
              return req.ToString();
          }

set-variable.value:
@{
            try {
                var r = (IResponse)context.Variables["classifierResponse"];
                if (r == null || r.StatusCode != 200) { return -1; }
                string verdict = ((string)r.Body.As<JObject>()["choices"][0]["message"]["content"] ?? "").Trim().ToLowerInvariant();
                if (verdict.StartsWith("simple")) { return 0; }
                if (verdict.StartsWith("medium")) { return 1; }
                if (verdict.StartsWith("complex")) { return 2; }
                return -1;
            } catch (Exception) { return -1; }
        }

@{
        string requested = (string)context.Variables["requestedModel"];
        if (requested == "tier-pym") { return "pym"; }
        if (requested == "tier-stark") { return "stark"; }
        if (requested == "tier-thanos") { return "thanos"; }
        if (requested.Length > 0 && requested != "heimdal-auto" && requested != "auto") { return "explicit"; }

        string mode = "{{router-mode}}";
        int lengthTier = (int)context.Variables["lengthTier"];
        int llmTier = (int)context.Variables["llmTier"];
        int complexityTier = llmTier >= 0 ? llmTier : (int)context.Variables["heuristicTier"];
        int t = mode == "length" ? lengthTier : (mode == "complexity" ? complexityTier : Math.Max(lengthTier, complexityTier));
        return t == 0 ? "pym" : (t == 1 ? "stark" : "thanos");
    }

@{
        string tier = (string)context.Variables["tier"];
        if (tier == "pym") { return "{{model-tier-pym}}"; }
        if (tier == "stark") { return "{{model-tier-stark}}"; }
        if (tier == "thanos") { return "{{model-tier-thanos}}"; }
        return (string)context.Variables["requestedModel"];
    }

@{
        string tier = (string)context.Variables["tier"];
        if (tier == "explicit") { return "client-selected-deployment"; }
        if (((string)context.Variables["requestedModel"]).StartsWith("tier-")) { return "client-forced-tier"; }
        return "mode=" + "{{router-mode}}" + ";complexity=" + "{{complexity-mode}}"
             + ";tokens~" + ((int)context.Variables["promptTokens"]).ToString()
             + ";score=" + ((int)context.Variables["complexityScore"]).ToString()
             + ";llmTier=" + ((int)context.Variables["llmTier"]).ToString();
    }

inbound.set-body:
@{
        var b = (JObject)context.Variables["body"];
        b["model"] = (string)context.Variables["routedModel"];
        // MAI models only accept max_completion_tokens
        if ((bool)context.Variables["isMai"] && b["max_tokens"] != null) {
            b["max_completion_tokens"] = b["max_tokens"];
            b.Remove("max_tokens");
        }
        return b.ToString();
    }
